def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The motif is the contiguous horizontal or vertical sequence of
    # non-background colors, excluding the repeated marker color.
    candidates = []
    for marker in set(v for row in grid for v in row if v != bg):
        for r in range(h):
            for c in range(w):
                if grid[r][c] != marker or marker == bg:
                    continue
                for dr, dc in ((0, 1), (1, 0)):
                    seq = []
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg:
                        seq.append(grid[rr][cc])
                        rr += dr
                        cc += dc
                    if len(seq) >= 2 and marker not in seq:
                        candidates.append((len(seq), marker, dr, dc, r, c, seq))

    # Choose the longest non-background run as the seed motif.
    if candidates:
        _, marker, dr, dc, r, c, motif = max(candidates)
        out = [row[:] for row in grid]
        mid = len(motif) // 2
        for i in range(h):
            for j in range(w):
                if grid[i][j] == marker:
                    for k, color in enumerate(motif):
                        rr = i + (k - mid) * dr
                        cc = j + (k - mid) * dc
                        if 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = color
        return out

    return [row[:] for row in grid]
